// Monta o e-mail (HTML com os dados escapados) e o texto do WhatsApp.
const dados = $input.first().json.body ?? {};
const lead = dados.lead ?? {};

const esc = (v) =>
  String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const ouTraco = (v) => (v === null || v === undefined || v === '' ? '—' : v);

const recebidoEm = lead.created_at
  ? new Date(lead.created_at).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', dateStyle: 'short', timeStyle: 'short' })
  : '—';
const servicos = (dados.servicos_labels ?? []).join(', ');
const area = lead.area_m2 ? `${Number(lead.area_m2).toLocaleString('pt-BR')} m²` : null;

const linhas = [
  ['Recebido em', recebidoEm],
  ['Nome', lead.nome],
  ['Telefone', lead.telefone],
  ['E-mail', lead.email],
  ['Empresa', lead.empresa],
  ['Perfil', dados.perfil_label],
  ['Serviços', servicos],
  ['Cidade da obra', lead.cidade],
  ['Área aproximada', area],
  ['Página de origem', lead.origem],
];

const linhaHtml = ([rotulo, valor]) =>
  `<tr><th align="left" style="padding:6px 12px 6px 0;color:#4a4a4a;font-weight:600;vertical-align:top;white-space:nowrap">${esc(rotulo)}</th><td style="padding:6px 0;color:#16202e">${esc(ouTraco(valor))}</td></tr>`;

const botao = (href, texto) =>
  href
    ? `<a href="${esc(href)}" style="display:inline-block;margin:0 8px 8px 0;padding:10px 16px;background:#0f2344;color:#ffffff;text-decoration:none;border-radius:4px;font-weight:600">${esc(texto)}</a>`
    : '';

const mensagemHtml = lead.mensagem
  ? `<h3 style="font-family:Georgia,serif;color:#0f2344;margin:24px 0 8px">Mensagem</h3><p style="white-space:pre-wrap;margin:0;color:#16202e">${esc(lead.mensagem)}</p>`
  : '';

const anexoHtml = dados.anexo_url
  ? `<p style="margin:16px 0 0;color:#4a4a4a">O cliente enviou um anexo. O link abaixo vale por 7 dias.</p>`
  : '';

const html = `<!doctype html><html lang="pt-BR"><body style="margin:0;padding:24px;background:#e8e8e6;font-family:Arial,Helvetica,sans-serif">
<div style="max-width:640px;margin:0 auto;background:#ffffff;border-top:6px solid #0f2344;padding:24px">
<h2 style="font-family:Georgia,serif;color:#0f2344;margin:0 0 4px">Novo pedido de orçamento</h2>
<p style="margin:0 0 16px;color:#4a4a4a">Enviado pelo site albanoluz.com</p>
<table cellpadding="0" cellspacing="0" style="border-collapse:collapse;font-size:14px">${linhas.map(linhaHtml).join('')}</table>
${mensagemHtml}
${anexoHtml}
<div style="margin-top:24px">${botao(dados.whatsapp_url, 'Responder no WhatsApp')}${botao(dados.anexo_url, 'Baixar anexo')}${botao(dados.painel_url, 'Abrir no painel')}</div>
</div></body></html>`;

const assunto = `Novo orçamento: ${lead.nome ?? 'sem nome'}${dados.perfil_label ? ` (${dados.perfil_label})` : ''}`;

const whatsapp = [
  '*Novo pedido de orçamento pelo site*',
  '',
  `*Nome:* ${ouTraco(lead.nome)}`,
  `*Telefone:* ${ouTraco(lead.telefone)}`,
  lead.email ? `*E-mail:* ${lead.email}` : null,
  lead.empresa ? `*Empresa:* ${lead.empresa}` : null,
  `*Perfil:* ${ouTraco(dados.perfil_label)}`,
  servicos ? `*Serviços:* ${servicos}` : null,
  lead.cidade ? `*Cidade:* ${lead.cidade}` : null,
  area ? `*Área:* ${area}` : null,
  lead.mensagem ? `*Mensagem:* ${String(lead.mensagem).slice(0, 400)}${String(lead.mensagem).length > 400 ? '…' : ''}` : null,
  dados.anexo_url ? '*Anexo:* sim (link no e-mail)' : null,
  '',
  dados.whatsapp_url ? `Responder: ${dados.whatsapp_url}` : null,
  dados.painel_url ? `Painel: ${dados.painel_url}` : null,
]
  .filter((l) => l !== null)
  .join('\n');

return [{ json: { assunto, html, whatsapp, responder_para: lead.email || '' } }];
